"""Generate one self-contained HTML artifact from JSON; no CDN or build chain."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
rows=json.loads((ROOT/'data'/'apps.json').read_text())
audit=json.loads((ROOT/'data'/'audit.json').read_text())
# Agent outputs may have been generated but NEVER treated as human checked.
p=ROOT/'data'/'agent_results.json'
if p.exists():
    agent=json.loads(p.read_text())
    for r in rows:
        v=agent.get(str(r['id']))
        if v and r['review']!='Docs reviewed' and 'second_pass' in v:
            d=v['second_pass']
            for field in ['auth','access','surface','mcp','blocker','note']:
                r[field]=d.get(field,r[field])
            r['evidence']=[e['url'] for e in d.get('evidence',[]) if e.get('url','').startswith('https://')]
            r['review']=v['review']

